.libPaths(c('work/Rlib',.libPaths()));library(survey);library(survival)
o<-readRDS('work/audit_models.rds');d<-o$data;out<-'outputs/final_analysis';d<-d[d$eligstat==1&d$weight>0&is.finite(d$cmibi_sd)&d$time>0,]
d$q<-cut(d$cmibi,quantile(d$cmibi,c(0,.25,.5,.75,1)),include.lowest=TRUE,labels=paste0('Q',1:4));ds<-svydesign(ids=~psu,strata=~stratum,weights=~weight,data=d,nest=TRUE)
rows<-list();for(v in c('ridageyr','bmxbmi','bmxwaist','sbp','dbp','lbxgh','lbxtr','lbdhdd','lbxtc','crp_mgl','egfr2021','lbxsua','lbxsal','lbxsapsi','cmibi')){r<-c(variable=v);for(q in levels(d$q)){x<-d[d$q==q,];r[q]<-sprintf('%.2f',weighted.mean(x[[v]],x$weight,na.rm=TRUE))};rows[[v]]<-as.data.frame(as.list(r))};write.csv(do.call(rbind,rows),file.path(out,'baseline_by_quartile.csv'),row.names=FALSE)
d$status<-factor(ifelse(d$mortstat!=1,'Censored',ifelse(d$cvd_death==1,'CVD',ifelse(d$cancer_death==1,'Cancer','Other'))),levels=c('Censored','CVD','Cancer','Other'))
aj<-survfit(Surv(time,status)~q,data=d,weights=weight/mean(weight),id=seqn)
png(file.path(out,'cvd_cumulative_incidence.png'),width=1600,height=1100,res=180);plot(aj,col=c('#476577','#4d8c8d','#b59053','#a3464e'),lwd=2,conf.int=FALSE,xlab='Years since examination',ylab='Cumulative incidence of CVD death',xlim=c(0,14),ylim=c(0,.1),noplot=setdiff(aj$states,'CVD'),main='Weighted Aalen-Johansen estimates');legend('topleft',levels(d$q),col=c('#476577','#4d8c8d','#b59053','#a3464e'),lwd=2,bty='n');dev.off()
# Age and sex confounding are not controlled in the cumulative incidence display.
cov<-'cmibi_sd+age10+indfmpir+education+race+pa_correct+bp_correct+dm_correct+lipid_med+strata(riagendr,smoking_cat)'
f<-as.formula(paste('Surv(time,cvd_death)~',cov));mm<-svycoxph(f,design=ds,ties='breslow',model=TRUE,x=TRUE,y=TRUE);b<-coef(mm)['cmibi_sd'];se<-sqrt(vcov(mm)['cmibi_sd','cmibi_sd']);df<-degf(ds)
write.csv(data.frame(n=mm$n,events=mm$nevent,HR=exp(b),lower=exp(b-qt(.975,df)*se),upper=exp(b+qt(.975,df)*se),p=2*pt(-abs(b/se),df)),file.path(out,'ph_stratified_sensitivity.csv'),row.names=FALSE)
png(file.path(out,'missingness_profile.png'),width=1600,height=1000,res=170);v<-c('indfmpir','smoking_cat','education','pa_correct','bp_correct','dm_correct','lipid_med');p<-colMeans(is.na(d[,v]))*100;par(mar=c(8,4,3,1));barplot(p,names.arg=c('Income','Smoking','Education','Activity','BP medication','Diabetes medication','Lipid medication'),las=2,col='#426b83',ylab='Missing covariates (%)',main='Missingness among 10,868 eligible participants');dev.off()
g<-read.csv(file.path(out,'GSE98895_metadata.csv'));png(file.path(out,'transcriptome_age_balance.png'),width=1400,height=950,res=170);boxplot(age~group,data=g,col=c('#88a6b6','#c58a8a'),ylab='Age (years)',xlab='',main='GSE98895 age imbalance');stripchart(age~group,data=g,vertical=TRUE,method='jitter',add=TRUE,pch=19,cex=.8);dev.off()
